"""Merge the aneurysms generated by run_inference.py into their patch masks (label 2 attached to the
artery, see inference/merge.py) and render the voxels for checking by eye.

  python scripts/ostium/run_merge.py --infer runtime_infer/ostium/abl_mlp_crop_norot_ep1000 \
      --graphs /media/yaplab2/HDD\\ Storage/wenhao/image-generation/debugging/graph1d_aneug_test

For aneurysm patches the real sac is removed first (the merge starts from the artery only); it is
drawn orange in the render for comparison. Writes, next to each sample:
  merged_XX.npz  the merged (z, y, x) uint8 mask (0, 1, 2), only for samples that were built
  merged_XX.png  render, two rows: voxels, then marching cubes (artery grey, generated sac blue, real sac orange)
and per case patch_overview.png: the whole patch with every built sac (translucent blue) and every
skipped dome (faint red), numbered by sample (--overview_only redraws just these)
and <infer>/merge_summary.json, merge_summary.md.
"""
import argparse
import collections
import json
import sys
from pathlib import Path

import numpy as np

REPO = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(REPO))


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--infer", required=True, help="output folder of run_inference.py")
    p.add_argument("--graphs", required=True, help="the same graph folder (graph.npz, meta.json, patch_seg.npy)")
    p.add_argument("--no_render", action="store_true")
    p.add_argument("--overview_only", action="store_true",
                   help="only (re)draw patch_overview.png per case from the saved merged_XX.npz and merge_summary.json")
    a = p.parse_args()
    from inference import merge as Mg
    from inference import ostium_inference as I
    from inference import render as Rd
    infer, graphs = Path(a.infer), Path(a.graphs)
    if a.overview_only:
        reps = json.loads((infer / "merge_summary.json").read_text())
        for cdir in sorted(d for d in infer.iterdir() if d.is_dir() and (graphs / d.name / "patch_seg.npy").exists()):
            overview(cdir, graphs / cdir.name, [r for r in reps if r["case"] == cdir.name], Mg, Rd)
        return
    reps = []
    for cdir in sorted(d for d in infer.iterdir() if d.is_dir() and (graphs / d.name / "patch_seg.npy").exists()):
        meta = json.loads((graphs / cdir.name / "meta.json").read_text())
        seg_orig = np.load(graphs / cdir.name / "patch_seg.npy")
        seg = np.where(seg_orig == 2, 0, seg_orig).astype(np.uint8)
        g = I.load_graph(graphs / cdir.name / "graph.npz")
        cs, n = meta["core_start_zyx"], meta["core_size"]
        core = [(cs[k], cs[k] + n) for k in range(3)]
        org, sp = meta["origin_xyz"], meta["spacing_xyz"]
        for f in sorted(cdir.glob("sample_*.npz")):
            z = np.load(f, allow_pickle=True)
            o = {k: z[k] for k in ("verts_mm", "faces", "p_dome", "frame")}
            o["site"] = int(z["site"])
            new, rep = Mg.merge_sample(seg, org, sp, o, g, core=core)
            k = f.stem.split("_")[1]
            rep.update(case=cdir.name, sample=int(k), built=new is not None)
            rep["accepted"] = rep["built"] and not rep.get("rejected")
            reps.append(rep)
            if new is not None:
                np.savez_compressed(cdir / f"merged_{k}.npz", seg=new)
            if not a.no_render:
                focus = z["ring_mm"].mean(0)
                show = {x: rep[x] for x in ("sac_volume_mm3", "neck_share", "crease_voxels", "pieces",
                                            "rim_move_median_mm", "rim_move_frac", "rim_inside_frac",
                                            "dome_in_parent_frac", "dome_in_other_vessel_frac", "flags") if x in rep}
                show.update({x: rep["shape"][x] for x in ("elongation", "thickness") if x in rep.get("shape", {})})
                view = new if new is not None else seg
                Rd.voxels(cdir / f"merged_{k}.png", view, org, sp, focus,
                          title=f"{cdir.name}  sample {k}" + ("" if new is not None else "  (NOT BUILT)")
                          + ("  (REJECTED: " + ", ".join(rep["rejected"]) + ")" if rep.get("rejected") else ""),
                          metrics=show, original=seg_orig if (seg_orig == 2).any() else None)
        if not a.no_render:
            overview(cdir, graphs / cdir.name, [r for r in reps if r["case"] == cdir.name], Mg, Rd)
        print(cdir.name, [("built" if r["built"] else ",".join(r["flags"])) for r in reps if r["case"] == cdir.name], flush=True)
    built = [r for r in reps if r["built"]]
    n_in = sum("rim_inside_lumen" in r["flags"] for r in built)
    acc = [r for r in built if r["accepted"]]
    L = [f"# Merge: {infer.name}", "", f"{len(reps)} samples: {len(acc)} accepted, {len(built) - len(acc)} built but rejected, "
         f"{len(reps) - len(built)} not built", "",
         "not built: " + (", ".join(f"{k} {v}" for k, v in collections.Counter(r["flags"][-1] for r in reps if not r["built"]).items()) or "none"),
         "rejected (a sample can have several): " + (", ".join(f"{k} {v}" for k, v in collections.Counter(
             f for r in built for f in r.get("rejected", [])).items()) or "none"), ""]
    if built:
        L += ["| built samples | median | 90th pct | max |", "|---|---|---|---|"]
        for k in ("sac_volume_mm3", "neck_share", "crease_voxels", "pieces", "specks_dropped_voxels",
                  "holes_filled", "rim_move_median_mm", "rim_move_max_mm", "voxels_outside_core",
                  "dome_in_parent_frac", "dome_in_other_vessel_frac"):
            v = np.array([r.get(k, 0) for r in built], float)
            L.append(f"| {k} | {np.median(v):.2f} | {np.percentile(v, 90):.2f} | {v.max():.2f} |")
        L += ["", "split sacs among built: " + str(sum("split_sac" in r["flags"] for r in built)),
              f"built with the rim inside the lumen (projected outwards): {n_in}", "",
              "| case | sample | status | flags | volume mm3 | in parent | in other vessel | elongation | thickness |",
              "|---|---|---|---|---|---|---|---|---|"]
        for r in reps:
            sh = r.get("shape", {})
            st = "accepted" if r["accepted"] else ("rejected" if r["built"] else "not built")
            L.append(f"| {r['case']} | {r['sample']} | {st} | {', '.join(r['flags'])} | {r.get('sac_volume_mm3', '')} | "
                     f"{r.get('dome_in_parent_frac', '')} | {r.get('dome_in_other_vessel_frac', '')} | "
                     f"{sh.get('elongation', float('nan')):.2f} | {sh.get('thickness', float('nan')):.2f} |")
    (infer / "merge_summary.json").write_text(json.dumps(reps, indent=1, default=float))
    (infer / "merge_summary.md").write_text("\n".join(L) + "\n")
    print("\n".join(L))


def overview(cdir, gdir, reps, Mg, Rd):
    """patch_overview.png: the whole patch, every built sac (blue) and every skipped dome (red)."""
    meta = json.loads((gdir / "meta.json").read_text())
    seg_orig = np.load(gdir / "patch_seg.npy")
    sacs, rejected, skipped, prompts = {}, {}, {}, {}
    for r in reps:
        k = f"{r['sample']:02d}"
        zs = np.load(cdir / f"sample_{k}.npz", allow_pickle=True)
        if "prompt_mm" in zs.files:
            prompts[r["sample"]] = zs["prompt_mm"]
        if r["built"]:
            (sacs if r.get("accepted", True) else rejected)[r["sample"]] = np.load(cdir / f"merged_{k}.npz")["seg"] == 2
        else:
            z = np.load(cdir / f"sample_{k}.npz", allow_pickle=True)
            dm = Mg.dome_patch(z["faces"], z["p_dome"])
            skipped[r["sample"]] = (z["verts_mm"], z["faces"][dm])
    Rd.patch_overview(cdir / "patch_overview.png", seg_orig, meta["origin_xyz"], meta["spacing_xyz"], sacs, skipped,
                      real_sac=seg_orig == 2, core_box=meta.get("core_box_mm"), rejected=rejected, prompts=prompts,
                      title=f"{cdir.name}: {len(sacs)} accepted (blue), {len(rejected)} rejected (red), "
                            f"{len(skipped)} not built (faint red)")


if __name__ == "__main__":
    main()
